import{_ as e,o as s,c as t,a5 as i}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"84. Cross-Compilation","description":"The Little Book of C — 84. Cross-Compilation","frontmatter":{"title":"84. Cross-Compilation","date":"2026-07-04","categories":["C 教程"],"tags":["C","Little Book of C","Portable and Modern C"],"description":"The Little Book of C — 84. Cross-Compilation","source":"https://little-book-of.github.io/c/books/en-US/book.html","license":"CC BY-NC-SA 4.0","originalAuthor":"Duc-Tam Nguyen","section":84,"sidebarWeight":84,"lang":"en-US","alternateEn":"/posts/c教程/en-US/09-Portable and Modern C/084-Cross-Compilation","alternateZh":"/posts/c教程/zh-CN/09-可移植与现代 C/084-Cross-Compilation"},"headers":[],"relativePath":"posts/c教程/en-US/09-Portable and Modern C/084-Cross-Compilation.md","filePath":"posts/c教程/en-US/09-Portable and Modern C/084-Cross-Compilation.md","lastUpdated":1790163617000}'),n={name:"posts/c教程/en-US/09-Portable and Modern C/084-Cross-Compilation.md"};function o(l,a,p,r,c,d){return s(),t("div",null,[...a[0]||(a[0]=[i(`<p>[中文版本](/posts/c教程/zh-CN/09-可移植与现代 C/084-Cross-Compilation)</p><p>Cross-compilation means building a program on one machine so it runs on another. If you’ve ever compiled a C program on your laptop and deployed it to a Raspberry Pi, an ESP32 board, or even a custom Linux image, you’ve done cross-compilation.</p><p>This is an essential skill for systems programmers, embedded developers, and anyone who builds for multiple architectures or operating systems.</p><h4 id="step-1-what-is-a-cross-compiler" tabindex="-1">Step 1. What Is a Cross-Compiler? <a class="header-anchor" href="#step-1-what-is-a-cross-compiler" aria-label="Permalink to &quot;Step 1. What Is a Cross-Compiler?&quot;">​</a></h4><p>A cross-compiler is a compiler that produces executables for a target platform different from the host platform.</p><table tabindex="0"><thead><tr><th>Term</th><th>Meaning</th></tr></thead><tbody><tr><td>Host</td><td>The system where you build the code</td></tr><tr><td>Target</td><td>The system where the program will run</td></tr><tr><td>Build</td><td>The system where the compiler itself was built (often same as host)</td></tr></tbody></table><p>Example: You’re on macOS (x86_64) and want to compile for a Raspberry Pi (ARM). Your toolchain must translate x86 instructions into ARM ones.</p><h4 id="step-2-why-cross-compile" tabindex="-1">Step 2. Why Cross-Compile? <a class="header-anchor" href="#step-2-why-cross-compile" aria-label="Permalink to &quot;Step 2. Why Cross-Compile?&quot;">​</a></h4><ul><li>Deploy software to embedded devices without compiling directly on them.</li><li>Build for multiple architectures from one workstation.</li><li>Generate portable binaries (for ARM, MIPS, RISC-V, etc.).</li><li>Prepare static binaries for minimal systems or containers.</li></ul><p>Cross-compilation is the foundation of embedded Linux, IoT, and firmware development.</p><h4 id="step-3-installing-a-cross-compiler" tabindex="-1">Step 3. Installing a Cross-Compiler <a class="header-anchor" href="#step-3-installing-a-cross-compiler" aria-label="Permalink to &quot;Step 3. Installing a Cross-Compiler&quot;">​</a></h4><p>On Linux, install a toolchain package for your target architecture. Examples:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo apt install gcc-arm-linux-gnueabihf</span></span>
<span class="line"><span>sudo apt install gcc-aarch64-linux-gnu</span></span>
<span class="line"><span>sudo apt install gcc-riscv64-linux-gnu</span></span></code></pre></div><p>Each toolchain contains:</p><ul><li><code>gcc</code> or<code>clang</code> cross-compiler</li><li><code>as</code>(assembler)</li><li><code>ld</code>(linker)</li><li>target system headers and libraries</li></ul><h4 id="step-4-verifying-the-target" tabindex="-1">Step 4. Verifying the Target <a class="header-anchor" href="#step-4-verifying-the-target" aria-label="Permalink to &quot;Step 4. Verifying the Target&quot;">​</a></h4><p>Check your compiler’s target triple:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>arm-linux-gnueabihf-gcc -v</span></span></code></pre></div><p>Output example:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Target: arm-linux-gnueabihf</span></span></code></pre></div><p>The triple encodes:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;architecture&gt;-&lt;vendor&gt;-&lt;OS&gt;-&lt;ABI&gt;</span></span></code></pre></div><p>For instance:</p><ul><li><code>x86_64-pc-linux-gnu</code></li><li><code>arm-none-eabi</code>(bare-metal, no OS)</li><li><code>aarch64-linux-gnu</code></li></ul><h4 id="step-5-compiling-for-another-platform" tabindex="-1">Step 5. Compiling for Another Platform <a class="header-anchor" href="#step-5-compiling-for-another-platform" aria-label="Permalink to &quot;Step 5. Compiling for Another Platform&quot;">​</a></h4><p>Tiny Code:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    printf(&quot;Hello from cross-compiled C!\\n&quot;);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Compile for ARM:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>arm-linux-gnueabihf-gcc hello.c -o hello_arm</span></span></code></pre></div><p>Transfer it to your ARM device:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>scp hello_arm user@raspberrypi.local:/home/user/</span></span></code></pre></div><p>Then run on the Pi:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>./hello_arm</span></span></code></pre></div><p>If everything’s configured correctly, you’ll see:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Hello from cross-compiled C!</span></span></code></pre></div><h4 id="step-6-static-vs-dynamic-linking" tabindex="-1">Step 6. Static vs Dynamic Linking <a class="header-anchor" href="#step-6-static-vs-dynamic-linking" aria-label="Permalink to &quot;Step 6. Static vs Dynamic Linking&quot;">​</a></h4><p>When cross-compiling, your target system might not have the same libraries. You can link everything into one binary:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>arm-linux-gnueabihf-gcc -static hello.c -o hello_static</span></span></code></pre></div><p>Static linking ensures the binary runs even if the target lacks shared libraries, useful for minimal or embedded systems.</p><h4 id="step-7-using-clang-for-cross-compilation" tabindex="-1">Step 7. Using Clang for Cross-Compilation <a class="header-anchor" href="#step-7-using-clang-for-cross-compilation" aria-label="Permalink to &quot;Step 7. Using Clang for Cross-Compilation&quot;">​</a></h4><p>Clang simplifies multi-target builds through<code>--target</code> and<code>--sysroot</code> options:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>clang --target=aarch64-linux-gnu --sysroot=/path/to/sysroot hello.c -o hello_arm64</span></span></code></pre></div><p><code>--sysroot</code> points to a directory that mimics the target’s filesystem, containing its headers and libraries.</p><h4 id="step-8-building-for-windows-or-macos-from-linux" tabindex="-1">Step 8. Building for Windows or macOS from Linux <a class="header-anchor" href="#step-8-building-for-windows-or-macos-from-linux" aria-label="Permalink to &quot;Step 8. Building for Windows or macOS from Linux&quot;">​</a></h4><p>You can also cross-compile across operating systems:</p><p>Linux → Windows:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo apt install mingw-w64</span></span>
<span class="line"><span>x86_64-w64-mingw32-gcc hello.c -o hello.exe</span></span></code></pre></div><p>Linux → macOS: More complex, usually requires Clang with Apple SDKs or<code>osxcross</code>.</p><h4 id="step-9-automating-with-cmake-or-makefiles" tabindex="-1">Step 9. Automating with CMake or Makefiles <a class="header-anchor" href="#step-9-automating-with-cmake-or-makefiles" aria-label="Permalink to &quot;Step 9. Automating with CMake or Makefiles&quot;">​</a></h4><p>CMake makes multi-platform builds easy.</p><p><code>toolchain-arm.cmake</code></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SET(CMAKE_SYSTEM_NAME Linux)</span></span>
<span class="line"><span>SET(CMAKE_SYSTEM_PROCESSOR arm)</span></span>
<span class="line"><span>SET(CMAKE_C_COMPILER arm-linux-gnueabihf-gcc)</span></span></code></pre></div><p>Then:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cmake -DCMAKE_TOOLCHAIN_FILE=toolchain-arm.cmake ..</span></span>
<span class="line"><span>make</span></span></code></pre></div><p>Your build system now knows it’s cross-compiling for ARM.</p><h4 id="step-10-tiny-code-detect-and-print-target-architecture" tabindex="-1">Step 10. Tiny Code: Detect and Print Target Architecture <a class="header-anchor" href="#step-10-tiny-code-detect-and-print-target-architecture" aria-label="Permalink to &quot;Step 10. Tiny Code: Detect and Print Target Architecture&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>#if defined(__x86_64__)</span></span>
<span class="line"><span>    printf(&quot;x86_64\\n&quot;);</span></span>
<span class="line"><span>#elif defined(__aarch64__)</span></span>
<span class="line"><span>    printf(&quot;ARM64\\n&quot;);</span></span>
<span class="line"><span>#elif defined(__arm__)</span></span>
<span class="line"><span>    printf(&quot;ARM 32-bit\\n&quot;);</span></span>
<span class="line"><span>#elif defined(__riscv)</span></span>
<span class="line"><span>    printf(&quot;RISC-V\\n&quot;);</span></span>
<span class="line"><span>#else</span></span>
<span class="line"><span>    printf(&quot;Unknown architecture\\n&quot;);</span></span>
<span class="line"><span>#endif</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Compile for different targets and observe the output.</p><h4 id="why-it-matters" tabindex="-1">Why It Matters <a class="header-anchor" href="#why-it-matters" aria-label="Permalink to &quot;Why It Matters&quot;">​</a></h4><p>Cross-compilation connects your laptop to every other device you’ll ever program. It’s how kernel modules, embedded systems, and even Android apps are built. Once you learn it, you can build anywhere, for anything.</p><h4 id="try-it-yourself" tabindex="-1">Try It Yourself <a class="header-anchor" href="#try-it-yourself" aria-label="Permalink to &quot;Try It Yourself&quot;">​</a></h4><ol><li>Install an ARM or RISC-V cross-compiler on your host system.</li><li>Cross-compile and run a simple “Hello” binary on an emulator (<code>qemu-arm</code>).</li><li>Use the<code>-static</code> flag to make it self-contained.</li><li>Add a Makefile with variables<code>CC</code>,<code>CFLAGS</code>, and<code>LDFLAGS</code> for easy reuse.</li><li>Try building both for Linux and Windows from the same source.</li></ol><p>Next, you’ll explore threading with pthreads, how to run multiple parts of your program at the same time using standard C threads.</p>`,63)])])}const m=e(n,[["render",o]]);export{u as __pageData,m as default};
